import openpyxl
wb = openpyxl.load_workbook('2_281-14_answer_template_8051_input.xlsx', data_only=False)
# Count occurrences per agent from numbered sheets
from collections import OrderedDict
agents = OrderedDict()
for name in ['2','3','4','7','8','9','10','11','14','22','23','24','25','28']:
    ws = wb[name]
    for row in ws.iter_rows(min_col=1, max_col=1):
        for c in row:
            v = c.value
            if v:
                agents.setdefault(v, []).append(int(name))
for a, days in agents.items():
    print(repr(a), days, 'count', len(days))
